/**
 * @brief Reverses a null-terminated string in place.
 *
 * @param str A pointer to the null-terminated string to be reversed.
 */
void reverseStringInPlace(char *str) {
    if (str == NULL) {
        return; // Handle the case where the input pointer is NULL
    }

    // 1. Initialize pointers for the start and end of the string
    int start = 0;
    int end = strlen(str) - 1;
    char temp;

    // 2. Loop until the start pointer crosses or meets the end pointer
    while (start < end) {
        // a. Store the character at the start position temporarily
        temp = str[start];

        // b. Replace the character at the start position with the character at the end position
        str[start] = str[end];

        // c. Replace the character at the end position with the stored character
        str[end] = temp;

        // d. Move the pointers inward
        start++;
        end--;
    }
}

