/**
 * Capitalizes the first letter of each word in a sentence.
 *
 * @param {string} sentence The input string to be capitalized.
 * @returns {string} The sentence with the first letter of each word capitalized.
 */
function capitalizeWords(sentence) {
  // 1. Handle edge cases: null, undefined, or empty string
  if (!sentence) {
    return "";
  }

  // 2. Convert the entire sentence to lowercase first to ensure consistency,
  //    especially if the input has mixed casing (e.g., "tHis iS a tEsT").
  const lowerCaseSentence = sentence.toLowerCase();

  // 3. Split the sentence into an array of words using space as the delimiter.
  const words = lowerCaseSentence.split(' ');

  // 4. Map over the array of words, capitalizing the first letter of each word.
  const capitalizedWords = words.map(word => {
    // Handle empty strings that might result from multiple spaces ("word  word")
    if (word.length === 0) {
      return "";
    }
    // Get the first character and convert it to uppercase
    const firstLetter = word.charAt(0).toUpperCase();
    // Get the rest of the word (from the second character onwards)
    const restOfWord = word.slice(1);
    // Combine them
    return firstLetter + restOfWord;
  });

  // 5. Join the array of capitalized words back into a single string with spaces.
  const result = capitalizedWords.join(' ');

  return result;
}

// --- Examples ---

console.log(`Example 1: "${capitalizeWords("hello world")}"`); // Output: "Hello World"
console.log(`Example 2: "${capitalizeWords("this is a test sentence")}"`); // Output: "This Is A Test Sentence"
console.log(`Example 3: "${capitalizeWords("already Capitalized")}"`); // Output: "Already Capitalized" (Handles existing caps by lowercasing first)
console.log(`Example 4: "${capitalizeWords("  leading and trailing spaces ")}"`); // Output: "  Leading And Trailing Spaces " (Handles extra spaces reasonably)
console.log(`Example 5: "${capitalizeWords("")}"`); // Output: "" (Empty string)
console.log(`Example 6: "${capitalizeWords(null)}"`); // Output: "" (Handles null)
console.log(`Example 7: "${capitalizeWords("one")}"`); // Output: "One"
```

### Explanation of the Approach:

1.  **Input Validation (`if (!sentence)`):** Checks if the input is null, undefined, or an empty string. If so, it immediately returns an empty string to prevent errors.
2.  **Normalization (`toLowerCase()`):** The entire sentence is converted to lowercase first. This is crucial because if we didn't do this, an input like `"tHis iS a tEsT"` would become `"THis IS A TEsT"`, which is technically correct but often not the desired output for title-casing. By lowercasing first, we ensure every word starts fresh.
3.  **Splitting (`split(' ')`):** The string is broken down into an array of individual words using the space character as the separator.
4.  **Mapping and Capitalizing (`map(...)`):**
